  1448  bool CodeStreamCompress::write_cbd()
  1449  {
  1450     uint32_t i;
  1451     auto image = getHeaderImage();
  1452     uint16_t cbd_size = (uint16_t)(6U + getHeaderImage()->numcomps);
  1453
  1454     /* CBD */
  1455     if(!stream_->writeShort(J2K_CBD))
  1456            return false;
  1457
  1458     /* L_CBD */
  1459     if(!stream_->writeShort((uint16_t)(cbd_size - 2U)))
  1460            return false;
  1461
  1462     /* Ncbd */
  1463     if(!stream_->writeShort(image->numcomps))
  1464            return false;
  1465
  1466     for(i = 0; i < image->numcomps; ++i)
  1467     {
  1468            auto comp = image->comps + i;
  1469            /* Component bit depth */
  1470            uint8_t bpc = (uint8_t)(comp->prec - 1);
  1471            if(comp->sgnd)
  1472                   bpc = (uint8_t)(bpc + (1 << 7));
  1473            if(!stream_->writeByte(bpc))
  1474                   return false;
  1475     }
  1476     return true;
  1477  }
